use std::io::{self, Read, Write};

/// One error type for the whole operation, with a message per cause.
#[derive(Debug)]
enum RecordError {
    Missing(&'static str),
    NotANumber(String),
    Negative(i64),
}

impl std::fmt::Display for RecordError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            RecordError::Missing(what) => write!(f, "missing {}", what),
            RecordError::NotANumber(t) => write!(f, "notanumber {}", t),
            RecordError::Negative(v) => write!(f, "negative {}", v),
        }
    }
}

/// ? on the Options (via ok_or) and on the Result (via map_err):
/// every failure leaves on the first line that can fail.
fn parse_record(fields: &[&str]) -> Result<(String, i64), RecordError> {
    let name = fields.first().ok_or(RecordError::Missing("name"))?;
    let qty_tok = fields.get(1).ok_or(RecordError::Missing("qty"))?;

    let qty: i64 = qty_tok
        .parse()
        .map_err(|_| RecordError::NotANumber((*qty_tok).to_string()))?;

    if qty < 0 {
        return Err(RecordError::Negative(qty));
    }

    Ok(((*name).to_string(), qty))
}

/// Option's own ?: None propagates, so no match is written.
fn second_word(line: &str) -> Option<&str> {
    let mut it = line.split_whitespace();
    it.next()?;
    it.next()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let mut ok_count = 0i64;
    let mut err_count = 0i64;
    let mut total = 0i64;

    for line in input.lines() {
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.is_empty() {
            continue;
        }

        match parse_record(&fields) {
            Ok((name, qty)) => {
                ok_count += 1;
                total += qty;
                writeln!(out, "ok {} {}", name, qty).unwrap();
            }
            Err(e) => {
                err_count += 1;
                writeln!(out, "err {}", e).unwrap();
            }
        }

        match second_word(line) {
            Some(w) => writeln!(out, "second {}", w).unwrap(),
            None => writeln!(out, "second none").unwrap(),
        }
    }

    writeln!(out, "records {}", ok_count).unwrap();
    writeln!(out, "errors {}", err_count).unwrap();
    writeln!(out, "total {}", total).unwrap();

    io::stdout().flush().ok();
}
